{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "Overly permissive IAM policy attachment",
      "resource": "aws_iam_policy_attachment.pass4",
      "severity": "MEDIUM",
      "explanation": "Attaching the managed policy 'AmazonS3ReadOnlyAccess' directly to a role can lead to excessive permissions if the role is used broadly. It is better to create a custom policy with the least privilege principle tailored to the specific needs of the role."
    }
  ],
  "patched_code": "resource "aws_iam_policy" "custom_s3_readonly" {
  name        = "custom_s3_readonly_policy"
  description = "Custom policy for S3 read-only access"

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "s3:GetObject",
        "s3:ListBucket"
      ],
      "Resource": [
        "arn:aws:s3:::example-bucket",
        "arn:aws:s3:::example-bucket/*"
      ]
    }
  ]
}
EOF
}

resource "aws_iam_policy_attachment" "pass4" {
  name       = "policy"
  role       = aws_iam_role.pass1.name
  policy_arn = aws_iam_policy.custom_s3_readonly.arn
}
",
  "fix_summary": "Replaced the use of the overly permissive managed policy 'AmazonS3ReadOnlyAccess' with a custom IAM policy that grants least privilege access to specific S3 actions and resources."
}
